{
  "title": "圆环石子合并的最值得分",
  "kind": "algorithm",
  "solution_idea": "把圆环从某处断开可视为在重复一遍的数组上取任意长度为 N 的连续区间。对任意线性区间 [l,r]，最后一次合并必然把区间分成 [l,k] 与 [k+1,r] 两段，本次得分为整个区间的石子和 sum(l,r)。因此有区间 DP 转移：dpMin[l][r]=min_k(dpMin[l][k]+dpMin[k+1][r]+sum(l,r))，dpMax 同理取 max。最优子结构成立，因为两段内部的合并互不影响，最后只额外加上两段总和。长度从 2 到 N 递推；N=1 时不需要操作，答案为 0 和 0。区间和可用重复数组上的前缀和 O(1) 得到。最终答案为所有长度为 N 的连续区间中 dpMin/dpMax 的最小/最大值。总复杂度 O(N^3)，空间 O(N^2)。",
  "methods": [
    {
      "name": "环形区间 DP（同时求最小与最大合并得分）",
      "knowledge_ids": [
        "dp.interval",
        "basic.prefix-sum"
      ],
      "time_complexity": "O(N^3)",
      "space_complexity": "O(N^2)"
    }
  ],
  "primary_knowledge_ids": [
    "dp.interval"
  ],
  "secondary_knowledge_ids": [
    "basic.prefix-sum"
  ],
  "evidence": {
    "dp.interval": "合并过程按区间最后一步分裂，需枚举断点并递推长度，求区间最小/最大得分。",
    "basic.prefix-sum": "在重复数组上预处理前缀和，使每次转移中的区间石子和可在 O(1) 内取得。"
  },
  "knowledge_confidence": {
    "dp.interval": 0.99,
    "basic.prefix-sum": 0.95
  },
  "confidence": 0.98
}

